* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #ffffff;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

#root {
  width: 100%;
  height: 100%;
  background: #ffffff;
}

.countdown-wrapper {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  background: #ffffff;
}

.countdown-card {
  width: 100%;
  min-height: 92px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 16px 20px;
  background: #ffffff;
  border: none;
  outline: none;
  box-shadow: none;
  border-radius: 0;
  color: #10264a;
}

.countdown-icon {
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  color: #2563eb;
  background: #eff6ff;
}

.countdown-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  text-align: center;
}

.countdown-label {
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-align: center;
}

.countdown-time {
  color: #10264a;
  font-size: 30px;
  line-height: 1.15;
  font-weight: 700;
  letter-spacing: 1px;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.countdown-card.expired {
  background: #ffffff;
}

.expired .countdown-icon {
  color: #dc2626;
  background: #fef2f2;
}

.expired .countdown-time {
  color: #dc2626;
}

@media (max-width: 320px) {
  .countdown-card {
    gap: 10px;
    padding: 12px;
  }
  .countdown-icon {
    width: 38px;
    height: 38px;
  }
  .countdown-time {
    font-size: 25px;
  }
  .countdown-label {
    font-size: 9px;
  }
}

