import React, { useState, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function CountdownDisplay() {
  const [time, setTime] = useState(
    appsmith.model?.countdownTime || "03:00"
  );

  useEffect(() => {
    // Update the UI whenever the Appsmith model changes
    const updateTime = () => {
      const value = appsmith.model?.countdownTime;

      if (value !== undefined && value !== null && value !== "") {
        setTime(String(value));
      }
    };

    updateTime();

    appsmith.onModelChange(() => {
      updateTime();
    });
  }, []);

  const isExpired = time === "00:00";

  return (
    <div className="countdown-wrapper">
      <div className={`countdown-card ${isExpired ? "expired" : ""}`}>
        <div className="countdown-icon">
          <svg
            viewBox="0 0 24 24"
            width="22"
            height="22"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <circle cx="12" cy="13" r="8.5" />
            <path d="M12 8v5l3 2" />
            <path d="M9 2h6" />
            <path d="M12 2v2.5" />
          </svg>
        </div>

        <div className="countdown-info">
          <span className="countdown-label">
            TIME REMAINING
          </span>

          <div className="countdown-time">
            {time}
          </div>
        </div>


      </div>
    </div>
  );
}

function App() {
  return <CountdownDisplay />;
}

ReactDOM.render(<App />, document.getElementById("root"));
